window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-1ea7a71659bdc155"]={"versions": [{"id": "FIG-1ea7a71659bdc155", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-ECU-Konfigurationsmodells (BSW-Modul FEE – Flash EEPROM Emulation). Es definiert die Metadaten- und Parameterstruktur des Konfigurationscontainers <code>FeeBlockConfiguration</code> und dessen Verknüpfung mit dem Flash-Treiber (<code>Fls</code>). Oberhalb des Diagramms beschreibt eine standardisierte ECUC-Metadatentabelle die Konfigurationsklassen und den Scope des Containers.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entität ist der Container <code>FeeBlockConfiguration</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..*).</p>\n<p class=\"fig-p\">Enthaltene Parameter (<code>+parameter</code> via Komposition):</p>\n<ul class=\"fig-list\">\n<li><code>FeeBlockSize</code> (<code>EcucIntegerParamDef</code>): Wertebereich 1 bis 65535.</li>\n<li><code>FeeBlockNumber</code> (<code>EcucIntegerParamDef</code>): Wertebereich 1 bis 65534, <code>symbolicNameValue = true</code>.</li>\n<li><code>FeeNumberOfWriteCycles</code> (<code>EcucIntegerParamDef</code>): Wertebereich 0 bis 4294967295.</li>\n<li><code>FeeImmediateData</code> (<code>EcucBooleanParamDef</code>): Boolescher Schalter für unmittelbare Datenbehandlung.</li>\n</ul>\n<p class=\"fig-p\">Referenz (<code>+reference</code> via Komposition):</p>\n<ul class=\"fig-list\">\n<li><code>FeeDeviceIndex</code> (<code>EcucReferenceDef</code>): <code>requiresSymbolicNameValue = true</code>, verweist über die Assoziation <code>+destination</code> auf den externen Container <code>FlsGeneral</code> (<code>EcucParamConfContainerDef</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurationsschema ohne Laufzeit- oder Sequenzinteraktion. Das Diagramm spezifiziert die Design- und Generierungszeit-Struktur für logische FEE-Blöcke. Jeder FEE-Block referenziert über den Geräteindex das zugrundeliegende Flash-Modul (<code>FlsGeneral</code>), um Adressierungs- und Zugriffsbeziehungen bei der Code-Generierung aufzulösen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Definition der Blockparameter für die statische BSW-Konfiguration. Gemäß tabellarischer Metadaten ist der Container rein lokal (<code>scope: local</code>), <code>Post-Build Variant Value = false</code> und die Werte-Konfigurationsklasse ist für alle Varianten ausschließlich zur Vorkompilierzeit (<code>Pre-compile time = X</code>, Link time <code>--</code>, Post-build time <code>--</code>) festgelegt. Enthaltene Sub-Container existieren nicht (<code>No Included Containers</code>). Die Blocknummerierung schließt symbolische Namen ein (<code>symbolicNameValue = true</code>), und die Treiberzuordnung erfordert symbolische Namen (<code>requiresSymbolicNameValue = true</code>).</p>"}, {"id": "FIG-733f50eed3275c10", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-ECU-Konfigurationsmodells (BSW-Modul FEE – Flash EEPROM Emulation). Es definiert die Metadaten- und Parameterstruktur des Konfigurationscontainers <code>FeeBlockConfiguration</code> und dessen Verknüpfung mit dem Flash-Treiber (<code>Fls</code>). Oberhalb des Diagramms beschreibt eine standardisierte ECUC-Metadatentabelle die Konfigurationsklassen und den Scope des Containers.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entität ist der Container <code>FeeBlockConfiguration</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..*).</p>\n<p class=\"fig-p\">Enthaltene Parameter (<code>+parameter</code> via Komposition):</p>\n<ul class=\"fig-list\">\n<li><code>FeeBlockSize</code> (<code>EcucIntegerParamDef</code>): Wertebereich 1 bis 65535.</li>\n<li><code>FeeBlockNumber</code> (<code>EcucIntegerParamDef</code>): Wertebereich 1 bis 65534, <code>symbolicNameValue = true</code>.</li>\n<li><code>FeeNumberOfWriteCycles</code> (<code>EcucIntegerParamDef</code>): Wertebereich 0 bis 4294967295.</li>\n<li><code>FeeImmediateData</code> (<code>EcucBooleanParamDef</code>): Boolescher Schalter für unmittelbare Datenbehandlung.</li>\n</ul>\n<p class=\"fig-p\">Referenz (<code>+reference</code> via Komposition):</p>\n<ul class=\"fig-list\">\n<li><code>FeeDeviceIndex</code> (<code>EcucReferenceDef</code>): <code>requiresSymbolicNameValue = true</code>, verweist über die Assoziation <code>+destination</code> auf den externen Container <code>FlsGeneral</code> (<code>EcucParamConfContainerDef</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurationsschema ohne Laufzeit- oder Sequenzinteraktion. Das Diagramm spezifiziert die Design- und Generierungszeit-Struktur für logische FEE-Blöcke. Jeder FEE-Block referenziert über den Geräteindex das zugrundeliegende Flash-Modul (<code>FlsGeneral</code>), um Adressierungs- und Zugriffsbeziehungen bei der Code-Generierung aufzulösen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Definition der Blockparameter für die statische BSW-Konfiguration. Gemäß tabellarischer Metadaten ist der Container rein lokal (<code>scope: local</code>), <code>Post-Build Variant Value = false</code> und die Werte-Konfigurationsklasse ist für alle Varianten ausschließlich zur Vorkompilierzeit (<code>Pre-compile time = X</code>, Link time <code>--</code>, Post-build time <code>--</code>) festgelegt. Enthaltene Sub-Container existieren nicht (<code>No Included Containers</code>). Die Blocknummerierung schließt symbolische Namen ein (<code>symbolicNameValue = true</code>), und die Treiberzuordnung erfordert symbolische Namen (<code>requiresSymbolicNameValue = true</code>).</p>"}, {"id": "FIG-3dcfd595e57b0ea9", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-ECU-Konfigurationsmodells des Moduls FEE (Flash EEPROM Emulation). Es zeigt die Konfigurationsparameter von <code>FeeBlockConfiguration</code> und dessen Schnittstellen bzw. Referenzen zur Hardware-Abstraktion (entweder <code>Fls</code> oder Memory Access / <code>MemAcc</code>). Dem Diagramm sind Tabellen für Konfigurationsklassen und eine Detaildefinition des Parameters <code>FeeMemAccAddressArea</code> vorangestellt.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entität ist <code>FeeBlockConfiguration</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..*).</p>\n<p class=\"fig-p\">Enthaltene Parameter (<code>+parameter</code>):</p>\n<ul class=\"fig-list\">\n<li><code>FeeBlockSize</code> (<code>EcucIntegerParamDef</code>): Wertebereich 1 bis 65535.</li>\n<li><code>FeeBlockNumber</code> (<code>EcucIntegerParamDef</code>): Wertebereich 1 bis 65534, <code>symbolicNameValue = true</code>.</li>\n<li><code>FeeNumberOfWriteCycles</code> (<code>EcucIntegerParamDef</code>): Wertebereich 0 bis 4294967295.</li>\n<li><code>FeeImmediateData</code> (<code>EcucBooleanParamDef</code>).</li>\n</ul>\n<p class=\"fig-p\">Referenzen (<code>+reference</code>):</p>\n<ul class=\"fig-list\">\n<li><code>FeeDeviceIndex</code> (<code>EcucReferenceDef</code>): Multiplizität 0..1, <code>requiresSymbolicNameValue = true</code>, zielend (<code>+destination</code>) auf <code>FlsGeneral</code> (<code>EcucParamConfContainerDef</code>).</li>\n<li><code>FeeMemAccAddressArea</code> (<code>EcucReferenceDef</code>): Multiplizität 0..1, <code>requiresSymbolicNameValue = true</code>, zielend (<code>+destination</code>) auf <code>MemAccAddressAreaConfiguration</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..65535).</li>\n</ul>\n<p class=\"fig-p\"><code>MemAccAddressAreaConfiguration</code> enthält als Parameter (<code>+parameter</code>) <code>MemAccAddressAreaId</code> (<code>EcucIntegerParamDef</code>, Wertebereich 0..65535, <code>defaultValue = 0</code>, Multiplizität 1..1, <code>symbolicNameValue = true</code>).</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell für die Konfigurations- und Generierungsphase. Die beiden Referenzen <code>FeeDeviceIndex</code> und <code>FeeMemAccAddressArea</code> stehen in einer wechselseitigen Ausschlussbeziehung (mutual exclusion): Ein Block wird entweder klassisch über den Flash-Treiber-Index (<code>FlsGeneral</code>) oder über die Adressbereichskonfiguration des Memory Access Moduls (<code>MemAccAddressAreaConfiguration</code>) angebunden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Konfigurationsanforderung mit Status <code>draft</code> für <code>FeeMemAccAddressArea</code> (SWS Item <code>ECUC_Fee_00155</code>). Die Multiplizitäten beider Treiber-Referenzen sind optional (0..1), schließen sich jedoch gegenseitig zwingend aus (<code>This reference is mutually exclusicve to FeeDeviceIndex</code> bzw. <code>FeeMemAccAddressArea</code>). Für <code>FeeMemAccAddressArea</code> sind Multiplicity- und Value-Konfigurationsklasse als Pre-compile time festgelegt (<code>All Variants</code>), Post-Build-Varianten sind unzulässig (<code>Post-Build Variant Multiplicity/Value = false</code>). Container <code>MemAccAddressAreaConfiguration</code> erlaubt bis zu 65535 Adressbereiche mit eindeutigen numerischen IDs.</p>"}, {"id": "FIG-eba9f58309c95850", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-ECU-Konfigurationsmodells des Moduls FEE (Flash EEPROM Emulation). Dargestellt ist die Struktur von <code>FeeBlockConfiguration</code> mit Anbindung an das Memory-Access-Konfigurationsmodell (<code>MemAcc</code>). Eine vorangestellte Tabelle definiert die Konfigurationsklassen und den Scope des Containers <code>FeeBlockConfiguration</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entität ist <code>FeeBlockConfiguration</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..*).</p>\n<p class=\"fig-p\">Enthaltene Parameter (<code>+parameter</code> via Komposition):</p>\n<ul class=\"fig-list\">\n<li><code>FeeBlockSize</code> (<code>EcucIntegerParamDef</code>): Wertebereich 1 bis 65535.</li>\n<li><code>FeeBlockNumber</code> (<code>EcucIntegerParamDef</code>): Wertebereich 1 bis 65534, <code>symbolicNameValue = true</code>.</li>\n<li><code>FeeNumberOfWriteCycles</code> (<code>EcucIntegerParamDef</code>): Wertebereich 0 bis 4294967295.</li>\n<li><code>FeeImmediateData</code> (<code>EcucBooleanParamDef</code>).</li>\n</ul>\n<p class=\"fig-p\">Referenz (<code>+reference</code> via Komposition):</p>\n<ul class=\"fig-list\">\n<li><code>FeeMemAccAddressArea</code> (<code>EcucReferenceDef</code>): Multiplizität 0..1, <code>requiresSymbolicNameValue = true</code>, verweist über <code>+destination</code> auf <code>MemAccAddressAreaConfiguration</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..65535).</li>\n</ul>\n<p class=\"fig-p\"><code>MemAccAddressAreaConfiguration</code> enthält den Parameter <code>MemAccAddressAreaId</code> (<code>EcucIntegerParamDef</code>, Wertebereich 0..65535, <code>defaultValue = 0</code>, Multiplizität 1..1, <code>symbolicNameValue = true</code>).</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurationsmodell zur Generierungszeit. Die FEE-Blöcke referenzieren über <code>FeeMemAccAddressArea</code> den logischen Adressbereich im Speichertreiber-Subsystem (<code>MemAccAddressAreaConfiguration</code>), über den Schreib-/Lesezugriffe auf das physikalische Medium abgewickelt werden. Es existiert keine direkte Referenz mehr zu herkömmlichen Fls-Treibern im Blockdiagramm.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für die Modulkonfiguration. Der Container <code>FeeBlockConfiguration</code> ist lokal (<code>scope: local</code>), erlaubt keine Untercontainer (<code>No Included Containers</code>) und schließt Post-Build-Varianten für Multiplizität und Werte aus (<code>Post-Build Variant Multiplicity = false</code>, <code>Post-Build Variant Value = false</code>). Sowohl Multiplicity Configuration Class als auch Value Configuration Class sind auf Pre-compile time für alle Varianten fixiert (<code>Pre-compile time = X</code>, Link time <code>--</code>, Post-build time <code>--</code>).</p>"}, {"id": "FIG-dc3bd330293f2d3b", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-ECU-Konfigurationsmodells für das BSW-Modul FEE (Flash EEPROM Emulation). Es stellt die Struktur des Containers <code>FeeBlockConfiguration</code>, dessen Parameter sowie die Referenzierung des Ziel-Containers <code>MemAccAddressAreaConfiguration</code> isoliert dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entität ist <code>FeeBlockConfiguration</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..*).</p>\n<p class=\"fig-p\">Enthaltene Parameter (<code>+parameter</code> via Komposition):</p>\n<ul class=\"fig-list\">\n<li><code>FeeBlockSize</code> (<code>EcucIntegerParamDef</code>): Wertebereich 1 bis 65535.</li>\n<li><code>FeeBlockNumber</code> (<code>EcucIntegerParamDef</code>): Wertebereich 1 bis 65534, <code>symbolicNameValue = true</code>.</li>\n<li><code>FeeNumberOfWriteCycles</code> (<code>EcucIntegerParamDef</code>): Wertebereich 0 bis 4294967295.</li>\n<li><code>FeeImmediateData</code> (<code>EcucBooleanParamDef</code>).</li>\n</ul>\n<p class=\"fig-p\">Referenz (<code>+reference</code> via Komposition):</p>\n<ul class=\"fig-list\">\n<li><code>FeeMemAccAddressArea</code> (<code>EcucReferenceDef</code>): Multiplizität 0..1, <code>requiresSymbolicNameValue = true</code>, verweist über <code>+destination</code> auf <code>MemAccAddressAreaConfiguration</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..65535).</li>\n</ul>\n<p class=\"fig-p\"><code>MemAccAddressAreaConfiguration</code> enthält den Parameter <code>MemAccAddressAreaId</code> (<code>EcucIntegerParamDef</code>, Wertebereich 0..65535, <code>defaultValue = 0</code>, Multiplizität 1..1, <code>symbolicNameValue = true</code>).</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurationsmodell zur Generierungszeit. Die FEE-Blöcke referenzieren über <code>FeeMemAccAddressArea</code> den logischen Adressbereich im Speichertreiber-Subsystem (<code>MemAccAddressAreaConfiguration</code>), über den Schreib-/Lesezugriffe auf das physikalische Medium abgewickelt werden. Es existiert keine direkte Referenz mehr zu herkömmlichen Fls-Treibern im Blockdiagramm.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Festlegung der Parameter- und Referenzstrukturen von <code>FeeBlockConfiguration</code>. Der Container besitzt eine Kardinalität von 1..*. Die Referenz <code>FeeMemAccAddressArea</code> ist mit Multiplizität 0..1 optional und erzwingt einen symbolischen Namen (<code>requiresSymbolicNameValue = true</code>). Die Zielkonfiguration <code>MemAccAddressAreaConfiguration</code> umfasst 1 bis 65535 Instanzen und verlangt für <code>MemAccAddressAreaId</code> eine eineindeutige Zuordnung (<code>symbolicNameValue = true</code>, Wertebereich 0..65535). Parametertabellen für Konfigurationsklassen und Post-Build-Eigenschaften sind nicht im Bild enthalten.</p>"}, {"id": "FIG-ffc25f1c5fcdcd44", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-ECU-Konfigurationsmodells für das BSW-Modul FEE (Flash EEPROM Emulation). Es stellt die Struktur des Containers <code>FeeBlockConfiguration</code>, dessen Parameter sowie die Referenzierung des Ziel-Containers <code>MemAccAddressAreaConfiguration</code> isoliert dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entität ist <code>FeeBlockConfiguration</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..*).</p>\n<p class=\"fig-p\">Enthaltene Parameter (<code>+parameter</code> via Komposition):</p>\n<ul class=\"fig-list\">\n<li><code>FeeBlockSize</code> (<code>EcucIntegerParamDef</code>): Wertebereich 1 bis 65535.</li>\n<li><code>FeeBlockNumber</code> (<code>EcucIntegerParamDef</code>): Wertebereich 1 bis 65534, <code>symbolicNameValue = true</code>.</li>\n<li><code>FeeNumberOfWriteCycles</code> (<code>EcucIntegerParamDef</code>): Wertebereich 0 bis 4294967295.</li>\n<li><code>FeeImmediateData</code> (<code>EcucBooleanParamDef</code>).</li>\n</ul>\n<p class=\"fig-p\">Referenz (<code>+reference</code> via Komposition):</p>\n<ul class=\"fig-list\">\n<li><code>FeeMemAccAddressArea</code> (<code>EcucReferenceDef</code>): Multiplizität 0..1, <code>requiresSymbolicNameValue = true</code>, verweist über <code>+destination</code> auf <code>MemAccAddressAreaConfiguration</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..65535).</li>\n</ul>\n<p class=\"fig-p\"><code>MemAccAddressAreaConfiguration</code> enthält den Parameter <code>MemAccAddressAreaId</code> (<code>EcucIntegerParamDef</code>, Wertebereich 0..65535, <code>defaultValue = 0</code>, Multiplizität 1..1, <code>symbolicNameValue = true</code>).</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurationsmodell zur Generierungszeit. Die FEE-Blöcke referenzieren über <code>FeeMemAccAddressArea</code> den logischen Adressbereich im Speichertreiber-Subsystem (<code>MemAccAddressAreaConfiguration</code>), über den Schreib-/Lesezugriffe auf das physikalische Medium abgewickelt werden. Es existiert keine direkte Referenz mehr zu herkömmlichen Fls-Treibern im Blockdiagramm.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Festlegung der Parameter- und Referenzstrukturen von <code>FeeBlockConfiguration</code>. Der Container besitzt eine Kardinalität von 1..*. Die Referenz <code>FeeMemAccAddressArea</code> ist mit Multiplizität 0..1 optional und erzwingt einen symbolischen Namen (<code>requiresSymbolicNameValue = true</code>). Die Zielkonfiguration <code>MemAccAddressAreaConfiguration</code> umfasst 1 bis 65535 Instanzen und verlangt für <code>MemAccAddressAreaId</code> eine eineindeutige Zuordnung (<code>symbolicNameValue = true</code>, Wertebereich 0..65535). Parametertabellen für Konfigurationsklassen und Post-Build-Eigenschaften sind nicht im Bild enthalten.</p>"}, {"id": "FIG-5f2185d416895b4c", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-ECU-Konfigurationsmodells für das BSW-Modul FEE (Flash EEPROM Emulation). Es stellt die Struktur des Containers <code>FeeBlockConfiguration</code>, dessen Parameter sowie die Referenzierung des Ziel-Containers <code>MemAccAddressAreaConfiguration</code> isoliert dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entität ist <code>FeeBlockConfiguration</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..*).</p>\n<p class=\"fig-p\">Enthaltene Parameter (<code>+parameter</code> via Komposition):</p>\n<ul class=\"fig-list\">\n<li><code>FeeBlockSize</code> (<code>EcucIntegerParamDef</code>): Wertebereich 1 bis 65535.</li>\n<li><code>FeeBlockNumber</code> (<code>EcucIntegerParamDef</code>): Wertebereich 1 bis 65534, <code>symbolicNameValue = true</code>.</li>\n<li><code>FeeNumberOfWriteCycles</code> (<code>EcucIntegerParamDef</code>): Wertebereich 0 bis 4294967295.</li>\n<li><code>FeeImmediateData</code> (<code>EcucBooleanParamDef</code>).</li>\n</ul>\n<p class=\"fig-p\">Referenz (<code>+reference</code> via Komposition):</p>\n<ul class=\"fig-list\">\n<li><code>FeeMemAccAddressArea</code> (<code>EcucReferenceDef</code>): Multiplizität 0..1, <code>requiresSymbolicNameValue = true</code>, verweist über <code>+destination</code> auf <code>MemAccAddressAreaConfiguration</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..65535).</li>\n</ul>\n<p class=\"fig-p\"><code>MemAccAddressAreaConfiguration</code> enthält den Parameter <code>MemAccAddressAreaId</code> (<code>EcucIntegerParamDef</code>, Wertebereich 0..65535, <code>defaultValue = 0</code>, Multiplizität 1..1, <code>symbolicNameValue = true</code>).</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurationsmodell zur Generierungszeit. Die FEE-Blöcke referenzieren über <code>FeeMemAccAddressArea</code> den logischen Adressbereich im Speichertreiber-Subsystem (<code>MemAccAddressAreaConfiguration</code>), über den Schreib-/Lesezugriffe auf das physikalische Medium abgewickelt werden. Es existiert keine direkte Referenz mehr zu herkömmlichen Fls-Treibern im Blockdiagramm.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Festlegung der Parameter- und Referenzstrukturen von <code>FeeBlockConfiguration</code>. Der Container besitzt eine Kardinalität von 1..*. Die Referenz <code>FeeMemAccAddressArea</code> ist mit Multiplizität 0..1 optional und erzwingt einen symbolischen Namen (<code>requiresSymbolicNameValue = true</code>). Die Zielkonfiguration <code>MemAccAddressAreaConfiguration</code> umfasst 1 bis 65535 Instanzen und verlangt für <code>MemAccAddressAreaId</code> eine eineindeutige Zuordnung (<code>symbolicNameValue = true</code>, Wertebereich 0..65535). Parametertabellen für Konfigurationsklassen und Post-Build-Eigenschaften sind nicht im Bild enthalten.</p>"}], "trans": [{"from": "FIG-1ea7a71659bdc155", "to": "FIG-733f50eed3275c10", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-733f50eed3275c10", "to": "FIG-3dcfd595e57b0ea9", "fr": "R20-11", "tr": "R21-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>FeeMemAccAddressArea</code> (<code>EcucReferenceDef</code>) mit Multiplizität 0..1 hinzugefügt (<code>requiresSymbolicNameValue = true</code>).</li>\n<li><code>MemAccAddressAreaConfiguration</code> (<code>EcucParamConfContainerDef</code>) mit Multiplizität 1..65535 als Referenzziel von <code>FeeMemAccAddressArea</code> hinzugefügt.</li>\n<li>Parameter <code>MemAccAddressAreaId</code> (<code>EcucIntegerParamDef</code>, Wertebereich 0..65535, <code>defaultValue = 0</code>, Multiplizität 1..1, <code>symbolicNameValue = true</code>) unter <code>MemAccAddressAreaConfiguration</code> hinzugefügt.</li>\n<li>Multiplizität für <code>FeeDeviceIndex</code> explizit als <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code> angegeben.</li>\n<li>Vorgelagerte Spezifikationstabelle zu <code>FeeMemAccAddressArea</code> (SWS Item <code>ECUC_Fee_00155</code>, Status <code>draft</code>) inklusive wechselseitigem Ausschluss (<code>mutually exclusive to FeeDeviceIndex</code>) oberhalb des Klassendiagramms ergänzt.</li>\n</ul>"}, {"from": "FIG-3dcfd595e57b0ea9", "to": "FIG-eba9f58309c95850", "fr": "R21-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Referenz <code>FeeDeviceIndex</code> (<code>EcucReferenceDef</code>) und Ziel-Container <code>FlsGeneral</code> (<code>EcucParamConfContainerDef</code>) entfernt.</li>\n<li>Spezifikationstabelle zu SWS Item <code>ECUC_Fee_00155</code> (<code>FeeMemAccAddressArea</code>) entfernt; die allgemeine Container-Kopfzeile für <code>FeeBlockConfiguration</code> (Post-Build-Klassifikation und Scope/Dependency) wieder als alleinige Tabelle über dem Diagramm platziert.</li>\n</ul>"}, {"from": "FIG-eba9f58309c95850", "to": "FIG-dc3bd330293f2d3b", "fr": "R22-11", "tr": "R23-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Vorgelagerte Tabellenzeilen (<code>Post-Build Variant Multiplicity</code>, <code>Post-Build Variant Value</code>, <code>Multiplicity Configuration Class</code>, <code>Value Configuration Class</code>, <code>Scope / Dependency</code>) sowie die Leiste <code>No Included Containers</code> oberhalb des Diagramms entfernt.</li>\n</ul>"}, {"from": "FIG-dc3bd330293f2d3b", "to": "FIG-ffc25f1c5fcdcd44", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-ffc25f1c5fcdcd44", "to": "FIG-5f2185d416895b4c", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
